/** Quote a CSV field when it contains a comma, quote or newline (RFC 4180). */
function field(value) {
  const text = value === null || value === undefined ? '' : String(value);
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

/**
 * Serialize rows to CSV with a header line. `columns` is a list of
 * { key, header } (header defaults to key); lines end with \r\n.
 */
export function toCsv(rows, columns) {
  const header = columns.map(column => field(column.header ?? column.key)).join(',');
  const body = rows.map(row => columns.map(column => field(row[column.key])).join(','));
  return [header, ...body].join('\r\n') + '\r\n';
}
