// Money is always stored as integer minor units (cents). Format only at the edges.

const MINOR_UNITS = { USD: 2, EUR: 2, GBP: 2, JPY: 0, KRW: 0 };
const SYMBOLS = { USD: '$', EUR: '€', GBP: '£', JPY: '¥', KRW: '₩' };

/**
 * Format integer minor units for display: formatCents(123456) === '$1,234.56',
 * formatCents(-500) === '-$5.00', formatCents(1200, 'JPY') === '¥1,200'.
 */
export function formatCents(cents, currency = 'USD') {
  if (!Number.isInteger(cents)) throw new TypeError('cents must be an integer');
  const digits = MINOR_UNITS[currency];
  if (digits === undefined) throw new RangeError(`Unsupported currency: ${currency}`);
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const major = Math.floor(abs / 10 ** digits);
  const minor = abs % 10 ** digits;
  const grouped = major.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}${SYMBOLS[currency]}${grouped}${digits ? '.' + String(minor).padStart(digits, '0') : ''}`;
}

/** Sum line totals (unitCents * quantity) in cents. */
export function sumCents(lines) {
  return lines.reduce((total, line) => total + line.unitCents * line.quantity, 0);
}
