import { businessDaysFrom, formatDay } from './lib/dates.mjs';
import { sumCents } from './lib/money.mjs';
import { paginate } from './lib/pagination.mjs';

export const ORDER_STATUSES = ['pending', 'paid', 'shipped', 'delivered', 'cancelled'];

/**
 * Order shape:
 * { id, customerId, status, currency, createdAt: Date,
 *   lines: [{ sku, name, unitCents, quantity }] }
 */
export const orderTotalCents = order => sumCents(order.lines);

/** Estimated ship date: 2 business days after the order, as 'yyyy-MM-dd'. */
export const estimatedShipDay = order => formatDay(businessDaysFrom(order.createdAt, 2));

/** Orders of one customer, newest first, paginated. */
export function customerOrders(orders, customerId, query = {}) {
  const mine = orders.filter(order => order.customerId === customerId).sort((a, b) => b.createdAt - a.createdAt);
  return paginate(mine, query);
}
