import assert from 'node:assert/strict';
import test from 'node:test';
import { customerOrders, estimatedShipDay, orderTotalCents } from '../src/orders.mjs';

const order = (id, customerId, day) => ({ id, customerId, status: 'paid', currency: 'USD', createdAt: new Date(2026, 0, day),
  lines: [{ sku: 'a', name: 'A', unitCents: 250, quantity: 2 }] });

