import { formatDay } from './lib/dates.mjs';
import { formatCents } from './lib/money.mjs';
import { toCsv } from './lib/csv.mjs';
import { orderTotalCents } from './orders.mjs';

/**
 * Orders as CSV with a header row: id, customer, status, total, created.
 * total is formatted in the order's currency (e.g. '$1,234.50');
 * created is the order date as 'yyyy-MM-dd'. Customer names are quoted as needed.
 */
export function ordersToCsv(orders) {
  const rows = orders.map(order => ({
    id: order.id,
    customer: order.customerName ?? order.customerId,
    status: order.status,
    total: formatCents(orderTotalCents(order), order.currency),
    created: formatDay(order.createdAt),
  }));
  return toCsv(rows, ['id', 'customer', 'status', 'total', 'created'].map(key => ({ key })));
}

